theorem completeAfter_of_smaller_card {a : Sequence} {m : ℕ}
    (hm : ∀ D : Finset ℕ, D.card = m → CompleteAfter a D)
    (D : Finset ℕ) (hD : D.card ≤ m) : CompleteAfter a D

theorem PrefixRep.add_term {a : Sequence} {N M i : ℕ} {x : ℤ}
    (h : PrefixRep a N x) (hNi : N ≤ i) (hiM : i < M) :
    PrefixRep a M (x + a i)

theorem prefixRep_erase_image {a : Sequence} {D : Finset ℕ} {N : ℕ} {x : ℤ}
    (h : PrefixRep (erase a D) N x) :
    ∃ s : Finset ℕ, s ⊆ (range N).image (survivor D) ∧ ∑ i ∈ s, a i = x

theorem exists_completeAfter_card_bounded {a : Sequence}
    (hm : Monotone a) (hb : ∃ B : ℤ, ∀ i, a i ≤ B) (hc : Complete a)
    (n : ℕ) : ∃ D : Finset ℕ, D.card = n ∧ CompleteAfter a D

theorem finiteCentralAfter_of_slack {a : Sequence}
    (hm : Monotone a) (ha : ∀ i, 0 < a i) (hd : DivergingSlack a)
    {D : Finset ℕ} (hc : CompleteAfter a D) : FiniteCentralAfter a D

theorem subset_range_of_sum_lt {a : Sequence} (hpos : ∀ i, 0 ≤ a i)
    (hmono : Monotone a) {s : Finset ℕ} {N : ℕ}
    (hs : ∑ i ∈ s, a i < a N) : s ⊆ range N

theorem representsAfter_negateAt {a : Sequence} {D : Finset ℕ} {j : ℕ}
    (hj : j ∉ D) {x : ℤ} (h : RepresentsAfter a D x) :
    RepresentsAfter (negateAt a j) D (x - a j)

theorem prefixSum_constant_tail {a : Sequence} {K : ℕ}
    (hK : ∀ n : ℕ, K ≤ n → a n = a K) (r : ℕ) :
    PrefixSum a (K + r) = PrefixSum a K + (r : ℤ) * a K

theorem sum_Ico_constant_tail {a : Sequence} {K : ℕ}
    (hK : ∀ n : ℕ, K ≤ n → a n = a K) (r : ℕ) :
    (∑ i ∈ Ico K (K + r), a i) = (r : ℤ) * a K

theorem central_intervals_of_eventually_constant {a : Sequence}
    (ha : ∀ i, 0 < a i) {K : ℕ}
    (hK : ∀ n : ℕ, K ≤ n → a n = a K)
    {T : ℤ} (hc : ∀ x : ℤ, T ≤ x → Represents a x) :
    CentralIntervals a T
